/* From Uiverse.io by jeremyssocial  - Tags: loader, dark, code */
/* Terminal Window */
.__UIV_SCOPE__ .terminal {
  width: 500px;
  background-color: #000;
  color: #0f0;
  font-family: "Courier New", Courier, monospace;
  border-radius: 8px;
  overflow: hidden;
  box-shadow: 0 0 15px rgba(0, 0, 0, 0.4);
}

/* Terminal Header */
.__UIV_SCOPE__ .terminal-header {
  background-color: #333;
  padding: 5px;
  display: flex;
  align-items: center;
  color: #fff;
}

.__UIV_SCOPE__ .buttons {
  display: flex;
  margin-right: 15px;
}

.__UIV_SCOPE__ .buttons span {
  height: 15px;
  width: 15px;
  border-radius: 50%;
  display: inline-block;
  margin-right: 5px;
}

.__UIV_SCOPE__ .close {
  background-color: #ff605c;
}
.__UIV_SCOPE__ .minimize {
  background-color: #ffbd44;
}
.__UIV_SCOPE__ .maximize {
  background-color: #00ca4e;
}

.__UIV_SCOPE__ .title {
  flex-grow: 1;
  text-align: center;
}

/* Terminal Body */
.__UIV_SCOPE__ .terminal-body {
  padding: 10px;
}

.__UIV_SCOPE__ .terminal-loader {
  display: inline-flex;
  align-items: center;
}

.__UIV_SCOPE__ .loader-text {
  margin-right: 5px;
}

.__UIV_SCOPE__ .dot {
  opacity: 0;
  animation: dotFadeInOut 1.5s infinite;
}

@keyframes dotFadeInOut {
  0%,
  100% {
    opacity: 0;
  }
  50% {
    opacity: 1;
  }
}

.__UIV_SCOPE__ #dot1 {
  animation-delay: 0.5s;
}

.__UIV_SCOPE__ #dot2 {
  animation-delay: 0.6s;
}

.__UIV_SCOPE__ #dot3 {
  animation-delay: 0.7s;
}
